_fpa.page_layouts = class {
  // Load columns within a standalone page.
  // This is typically called when the page is loaded,
  // or through specific post processors, for example if
  // we embed a page layout in a standalone (portal) page
  static load_columns(target) {
    if (target) {
      // If this is a jQuery target, get the id to use, otherwise use the string provided or just set it to empty string
      if (target.attr) target = `#${target.prop('id')} `
      else target = `${target} `
    } else target = ''

    // Get the columns within the target and fire the URL for each specified in the data-url="" attribute
    $(`${target}.standalone-page-col`).each(function () {
      var block = $(this);
      var url = block.attr('data-url');
      _fpa.send_ajax_request(url, {
        try_app_callback: function (el, data) {
          var tb = block.find('.result-target-report');
          // If we are supposed to be returning a report result, process that
          if (tb.length > 0) {
            tb.html(data);
            _fpa.postprocessors.reports_result(block, {});
          }
          else {
            // We are processing a resource such as dynamic model or activity log. Handle the latter explicitly
            _fpa.page_layouts.handle_activity_log(block);
          }
          block.removeClass('ajax-running');
        }
      });

    });

  }

  // Activity logs embedded in the dashboards or standalone portal pages require controls to be stripped out
  // for more pleasing presentation. Handle this
  static handle_activity_log(block) {
    const tb = block.find('.result-target-resource');
    if (tb.length > 0) {
      window.setTimeout(function () {
        tb.find('.standalone-panel-generic-block.collapse').show();
        if (!tb.hasClass('keep-activity-log-sublist-controls')) {
          tb.find('.sublist-controls').remove();
        }
        if (!tb.hasClass('keep-activity-log-section-panel-header')) {
          tb.find('.section-panel-header').remove();
        }
        if (!tb.hasClass('keep-activity-log-header') && !tb.hasClass('keep-activity-log-action-buttons')) {
          tb.find('.activity-logs-header, .new-blocks-container').remove();
        }

        if (!tb.hasClass('keep-activity-log-header')) {
          tb.find('.activity-logs-header .list-group-item-heading').remove();
        }

        if (!tb.hasClass('keep-activity-log-action-controls')) {
          tb.find('.activity-logs-header .action-buttons, .new-blocks-container').remove();
        }

        tb.find('.panel.panel-default').removeClass('panel panel-default');
        tb.find('.common-template-item').addClass('col-md-24 col-lg-24').removeClass('col-md-8 col-lg-6 col-md-12 col-lg-12').css({ minHeight: 'auto' });
      }, 600);

    }
  }

};
_fpa.report_criteria = class {

  static reports_form(block, data) {
    _fpa.form_utils.format_block(block);
    _fpa.reports.get_results_block().html('');


    _fpa.report_criteria.handle_search_form(block.find('form'));

    var by_auto_search_btn = $('#report-form-auto-submitter-btn');
    by_auto_search_btn.not('.asclick-attached').on('click', function () {
      by_auto_search_btn.attr('data-submitted', 'true');
    }).addClass('asclick-attached');

    block.find('a.btn[data-attribute]').click(function (ev) {
      ev.preventDefault();
      var da = $(this).attr('data-attribute');

      var v = $('#search_attrs_' + da);
      var newval = v.val();
      if (newval.length > 0) newval += "\n";
      var from_f = $('#multiple_attrs_' + da);
      var boxval = from_f.val();
      // Prevent empty values being put into the list
      if (boxval) {
        newval += boxval;
        v.val(newval);
        from_f.val('');
        v.change();
        from_f.change();
      }
    });

    block.find('form').not('.attached-complete-listener').on('submit', function () {
      // If there is a multivalue criteria field, ensure a field in the text box is added when we submit the form
      $('.multivalue-field-add').click();

    }).on('ajax:complete', function () {
      $('#search_attrs__filter_previous_').attr('checked', false);
      $('#filter_on_block').html('');
    }).addClass('attached-complete-listener');

    var cb = $('#search_attrs__filter_previous_').not('.attached-click-listener');
    var show_fob;
    if (cb.length === 1 && cb.is(':checked')) {
      window.setTimeout(function () {
        $('a#get_filter_previous').click();
      }, 100);
      show_fob = true;
    }

    cb.on('change', function () {
      if (!$('#search_attrs__filter_previous_').is(':checked')) {
        $('#filter_on_block').html('');
      } else {
        window.setTimeout(function () {
          $('a#get_filter_previous').click();
        }, 100);
      }
      return false;
    }).addClass('attached-click-listener');

    if (!show_fob) block.find('[type="submit"].auto-run').not('.was-auto-run-clicked').addClass('was-auto-run-clicked').click();

  };

  static handle_search_form(forms) {

    // Step through all the search or report criteria forms
    forms.each(function () {
      var f = $(this);

      f.find('input[type="submit"]').on('click', function (e) {
        if (_fpa.state.search_running) {
          e.preventDefault();
          return;
        }
      });

      // For every input and drop down on the form that is not a
      // typeahead field and is not already processed
      // check for changes
      // We add a class attached-change at the end to indicate that this field has been
      // has been processed and should not have another listener attached. Can avoid hard to debug
      // issues and provide extra information when looking at what has and hasn't been changed in the DOM
      f.find('input, select, textarea').not('.no-auto-submit, .tt-input, .attached-change, [type="submit"]').on('change', function (e) {

        // Cancel any search-related Ajax requests that are still running
        _fpa.cancel_remote();


        // Handle the [data-only-for] marked up fields as special cases.
        // These fields will not automatically submit the form when changed, since they
        // are typically used to filter the content of a related select field.
        var dof = $(this).attr('data-only-for');
        var v = $(this).val();
        var all_null = true;
        if (dof) {
          // Allow multiple fields, any one of which may be entered
          $(dof).each(function () {
            var el = $(this);
            if (el.val() !== null && el.val() !== '' && !el.hasClass('prevent-submit')) all_null = false;
          });
        }
        if (!dof || !all_null) {
          // Assuming that we are not in data-only-for field, and all the fields on the form are not null,
          // then fire a submit
          // We do this within a timeout, to allow any DOM changes and CSS transitions to smoothly work through
          // otherwise the result is a very jerky experience
          // We delay longer than necessary to allow a form submit button click to process first, preventing this blocking
          // a valid button click
          window.setTimeout(function () {
            if (!_fpa.state.search_running) {
              var bel = f.find('[type="submit"].auto-submitter');
              if (bel.length > 0) {
                bel.click();
                _fpa.state.search_running = true;
              }
            }
          }, 20);
        }
        // Clean up after ourselves
        $('.prevent-submit').removeClass('prevent-submit');

      }).addClass('attached-change');

      // Specifically for typeahead fields, we need to explicitly submit on blur. We assume that a typeahead can not
      // be a data-only-for field
      f.find('input.tt-input').not('.attached-change').on('blur', function (e) {
        window.setTimeout(function () {
          f.find('[type="submit"].auto-submitter').click();
        }, 1);
      }).addClass('attached-change');

      var $dfs = f.find('[data-filter-selector]');
      $dfs.on('change', function () {
        var fts = $(this).attr('data-filter-selector')
        _fpa.form_utils.select_filtering_changed($(this).val(), `[name="search_attrs[${fts}]"]`)
      }).each(function () {
        var fts = $(this).attr('data-filter-selector')
        _fpa.form_utils.select_filtering_changed($(this).val(), `[name="search_attrs[${fts}]"]`)
      });

      _fpa.form_utils.setup_chosen_groups($dfs);


      f.find('[type="submit"]').click(function () {
        var v = $(this).val();
        var dov = false;
        if (v === 'csv' || v === 'json') {
          dov = true;
        }
        var f = $(this).parents('form').first();
        // Must use data('remote') to disable the rails AJAX delegation. Setting the attribute doesn't work.
        f.data('remote', !dov).attr('target', (dov ? v : null));
        // For the report forms, set the 'part' to return appropriate results
        f.find('input[name="part"]').val(dov ? '' : 'results');

        if (dov) {
          $('#master_results_block').html('<h3 class="text-center">Exported ' + v + '</h3>');

          // UJS disables the buttons, but only ajax responses re-enable them.
          // For csv and json export requests, re-enable by hand
          window.setTimeout(function () {
            console.log('here')
            f.find('input[type="submit"][disabled], button[type="submit"][disabled]').attr('disabled', null).prop('disabled', null);
          }, 1500);
        }
      });
    }).on('keypress', function (e) {
      // On any keypress inside a form, cancel an existing ajax search, since the user is probably doing something else
      _fpa.cancel_remote();
    }).on('submit', function () {
      // When we submit the form, give the user a visual spinner so they know what's going on
      // This also clears existing search results to make it clear when a result is complete
      if ($(this).data('remote'))
        _fpa.reports.get_results_block().html('<h3 class="text-center"><span class="glyphicon glyphicon-search search-running"></span></h3>');
    });

  }

};
_fpa.loaded.reports = function () {

  const $criteria_form = $('.report-criteria');
  _fpa.report_criteria.reports_form($criteria_form);
  $('.postprocessed-scroll-here').removeClass('postprocessed-scroll-here').addClass('prevent-scroll');

  // If this an editable data form, automatically submit it if there are no criteria fields to enter
  if ($('#editable_data').length == 1 && $('.report-criteria-fields').length >= 1)
    $('input[type="submit"][value="table"]').click();

  // Substitute list_id param into links in the report criteria containing :list_id
  // This only functions for full page reports, not embedded reports
  const $a_to_list = $criteria_form.find('a[href*=":list_id"]');
  const param_list_match = location.href.match(/\[list_id\]=(\d+)/);
  if ($a_to_list.length && param_list_match) {
    const param_list_id = parseInt(param_list_match[1]);

    $a_to_list.each(function () {
      var url = $(this).attr('href');
      url = url.replace(':list_id', param_list_id);
      $(this).attr('href', url);
    });
  }

};

_fpa.reports = {

  window_scrolling: function () {
    $('html').on('wheel', function (e) {
      if (e.originalEvent.deltaY > 0 && $('.chosen-container-active').length == 0) {
        _fpa.reports.report_position_buttons('go-to-results');
        _fpa.reports.reset_window_scrolling();
      }
    });
  },
  reset_window_scrolling: function () {
    $('html').off('wheel');
  },
  report_position_buttons: function (to_loc) {
    var sb = $('.show-results-btn');
    var rf = $('.back-to-search-form-btn');
    if (sb.length == 0 && rf.length == 0) {
      return;
    }

    sb.not('.has-rsf-clicks').click(function (e) {
      e.preventDefault();
      _fpa.reports.report_position_buttons('go-to-results');
    }).addClass('has-rsf-clicks');
    rf.not('.has-rsf-clicks').click(function (e) {
      e.preventDefault();
      _fpa.reports.report_position_buttons('go-to-form');
    }).addClass('has-rsf-clicks');

    if (to_loc == 'go-to-results') {
      sb.hide();
      rf.show();
      _fpa.reports.reset_window_scrolling();
      $.scrollTo('.report-results-block', 200);
    }
    else if (to_loc == 'go-to-form') {
      sb.show();
      rf.hide();
      _fpa.reports.window_scrolling();
      $.scrollTo('#body-top', 200);
    }
    // window.location.hash = '';
  },
  results_subsearch: function (block) {
    block.find('td[data-col-type^="search_reports_"]').not('.attached_report_search').each(function () {
      var dct = $(this).attr('data-col-type');
      if (!$(this).hasClass('attached_report_search') && dct.match(/search_reports_[0-9]+_.+/)) {
        var dct_parts = dct.split('_', 4);

        var dct_field = dct_parts[3];
        var dct_report = dct_parts[2];
        var dct_search = $(this).html().trim();

        var url = "/reports/" + dct_report + ".json?&search_attrs[" + dct_field + "]=" + dct_search + "&commit=search";

        var new_l = $('<a href="' + url + '" data-remote="true" data-result-target="#modal_results_block" data-result-target-force="true" data-template="modal-pi-search-results-template" title="click to search">' + $(this).html() + '</a>');

        $(this).html(new_l);
        $(this).addClass('attached_report_search')
        new_l.click(function () {
          var h = '<div id="modal_results_block" class=""></div>';

          _fpa.show_modal(h, "Search results for " + dct_search, true);

        });
      }
    }).addClass('attached_report_search');
  },

  results_perform_action_link: function (block) {
    block.find('td[data-col-type^="perform action:"]').not('.attached_report_perform_action').each(function () {

      var dct = $(this).attr('data-col-type');

      var dct_parts = dct.split(':', 2);
      var dct_action = dct_parts[1];
      var orig_action = dct_parts[1];
      var dct_json = $(this).html();

      if (!dct_json || dct_json == '') return;

      var act_config = JSON.parse(dct_json);
      var base_url = act_config.perform_action;
      delete act_config.perform_action;

      if (act_config.label) {
        dct_action = act_config.label;
        delete act_config.label;
      }

      var params = {};
      for (var k in act_config) {
        if (act_config.hasOwnProperty(k)) {
          var v = act_config[k];
          if (base_url.indexOf('!' + k) >= 0) {
            base_url = base_url.replace('!' + k, v);
          }
          else {
            params[k] = v
          }
        }
      }

      var dctaus = 'report_' + orig_action.underscore();

      var pstring = $.param(params);

      var new_html = '<a href="' + base_url + '?' + pstring + '" target="report-perform-action" class="' + dctaus + '">' + dct_action + '</a>';

      $(this).html(new_html);

      if (orig_action.trim() == 'view file') {
        _fpa.secure_view.setup_links($(this), 'a.' + dctaus);
        $('a.' + dctaus).on('click', function (ev) {
          ev.preventDefault();
        });
      }



    }).addClass('attached_report_perform_action');

  },


  // Add checkboxes to a report table to allow individual items to be selected and
  // passed to the server for saving in a list model.
  // The SQL would include a field like this:
  // '{"field_name": "update_list[items][]", "value": {"list_id": "' || :list_id ||
  //   '","type":"datadic_variable", "id": ' || cb.id ||
  //   ', "from_master_id":-1, "init_value": ' ||
  //   case when coalesce(sel.id, 0) = 0 then 'false' else 'true' end
  //   || '}}'
  //   "select items: update list: data_requests_selected_attribs"
  //
  // To add multiple items in a single cell, change the JSON to an array of multiple items, something like the following.
  // Note a label entry is provided at the top level of each item to allow identification of what is being selected by the user.
  // '[{"field_name": "update_list[items][]", "label": "pick - ' || cb.name || '", "value": {"list_id": "' || :list_id ||
  //   '","type":"datadic_variable", "id": ' || cb.id ||
  //   ', "from_master_id":-1, "init_value": ' ||
  //   case when coalesce(sel.id, 0) = 0 then 'false' else 'true' end
  //   || '}}, ' ||
  //   '{"field_name": "update_list[items][]", "label": "alt pick - ' || cb.name || '", "value": {"list_id": "' || :list_id ||
  //   '","type":"datadic_variable", "id": ' || cb.alt_id  ||
  //   ', "from_master_id":-1, "init_value": ' ||
  //   case when coalesce(sel.id, 0) = 0 then 'false' else 'true' end
  //   || '}}'
  //   "select items: update list: data_requests_selected_attribs"


  results_select_items_for_form: function (block) {

    var dct;
    var dct_parts;

    var $outer = block.parents('.modal-body, body').first().parent();

    block.find('td[data-col-type^="chart:"]').not('.attached_report_chart').each(function () {

      var row = $(this).parent();
      var chart_dct = $(this).attr('data-col-type');

      // chart_dct_parts = chart_dct.split(':', 3);

      var chart_dct_json = $(this).html();

      if (!chart_dct_json || chart_dct_json == '') return;

      // Get values like "colval.xyz" for substitution
      var cols = chart_dct_json.match(/colval\.[a-zA-Z0-9_]+/g);

      if (cols) {
        for (var i = 0; i < cols.length; i++) {
          var c = cols[i];
          var cname = c.split('.')[1];
          var colval = row.find('td[data-col-type="' + cname + '"]').html();
          if (colval) {
            colval = colval.trim()
          } else {
            colval = null;
          }

          chart_dct_json = chart_dct_json.replace(c, colval);
        }
      }

      var chart_act_config = JSON.parse(chart_dct_json);

      chart_act_config.options = chart_act_config.options || {};
      // chart_act_config.options.legend = chart_act_config.options.legend || {display: false};

      var name = chart_act_config.label;
      var value = chart_act_config;

      var width = chart_act_config.width;
      var height = chart_act_config.height;

      if (width || height) {
        var fixed_size = true;
      }

      width = width || 100;
      height = height || 100;

      chart_act_config.options.responsive = !fixed_size;

      var new_html = $('<canvas width="' + width + '" height="' + height + '"></canvas>');

      $(this).html(new_html);

      var ctx = $(this).find('canvas');
      var myPieChart = new Chart(ctx, value);

      var head = $outer.find('th[data-col-type="' + chart_dct + '"]').not('.added-chart-legend');
      if (head.length > 0) {
        var headp = head.find('p.table-header-col-type');
        headp.html(name);
        head.addClass('no-sort added-chart-legend');
      }



    }).addClass('attached_report_chart');

    var cb_id = 0;

    block.find('.report-results-table-block td[data-col-type^="select items:"], .report-results-list-block div[data-col-type^="select items:"]').not('.attached_report_select_items').each(function () {

      dct = $(this).attr('data-col-type');

      dct_parts = dct.split(':', 3);

      // If this is a list view, use the <rldata> element for content
      var $el = $(this)
      if ($el.find('rldata').length) $el = $el.find('rldata')

      var dct_json = $el.html();

      if (!dct_json || dct_json.trim() == '') return;

      var act_configs = JSON.parse(dct_json);
      if (dct_json[0] == '{') {
        act_configs = [act_configs]
      }

      $el.html('');

      Object.values(act_configs).forEach((act_config) => {

        var name = act_config.field_name;
        var value = act_config.value;
        var checked = act_config.value.init_value ? 'checked="checked"' : ''
        var dis = act_config.disabled ? 'disabled="disabled"' : ''
        var h = `<input type="checkbox" class="report-file-selector" id="seicb-${cb_id}" name="${name}" ${checked} ${dis}/>`;
        var $h = $(h);
        $h.val(JSON.stringify(value));
        var $eldiv = $('<div class="report-sel-item-ind"></div>').appendTo($el);
        $eldiv.append($h);
        if (act_config.label) {
          var $label = `<label for="seicb-${cb_id}">${act_config.label}</label>`
          $eldiv.append($label);
        }
        cb_id++;
      })

    }).addClass('attached_report_select_items');

    if (!dct_parts) return;

    var dct_action = dct_parts[1].trim();
    if (dct_parts[2]) {
      var extra_val = dct_parts[2].trim();
    }

    var report_id = $outer.find('.report-container').first().attr('data-report-id');


    if (dct_action == 'download files') {
      var $f = $('<form id="itemselection-for-report" method="post" action="/nfs_store/downloads/multi" target="download_files"><input type="hidden" name="nfs_store_download[container_id]" value="multi"><input name="authenticity_token" type="hidden" class="set-auth-token" value="" /></form>');
      _fpa.form_utils.set_auth_tokens($f);
    }
    else if (dct_action == 'add to list') {
      var $f = $(`<form id="itemselection-for-report" method="post" action="/reports/${report_id}/add_to_list.json" class="report-add-to-list" data-remote="true"><input type="hidden" name="add_to_list[list_name]" value="${extra_val}"></form>`);
    }
    else if (dct_action == 'update list') {
      var $f = $(`<form id="itemselection-for-report" method="post" action="/reports/${report_id}/update_list.json" class="report-update-list" data-remote="true"><input type="hidden" name="update_list[list_name]" value="${extra_val}"></form>`);
    }
    else if (dct_action == 'remove from list') {
      var $f = $(`<form id="itemselection-for-report" method="post" action="/reports/${report_id}/remove_from_list.json" class="report-remove-from-list" data-remote="true"><input type="hidden" name="remove_from_list[list_name]" value="${extra_val}"></form>`);

      var cblock = $outer.find('[data-result="#report-embedded"]').first();
      if (cblock.length == 0) cblock = $('body');

      cblock.find('#report_query_form').addClass('keep-notices');
      $f.on('ajax:success', function (e, data, status, xhr) {
        cblock.find('#report-form-submit-btn').addClass('keep-notices').click();
      });

    }
    var $fsels = $outer.find('.report-file-selector');
    var all_selected = ($fsels.filter(':checked').length > 0);
    var checked_attr = all_selected ? 'checked' : '';
    var init_label = all_selected ? 'unselect all' : 'select all'

    var b = `<span class="report-files-actions"><a id="report-select-all-files" data-select-all="select">select all</a> / <a id="report-unselect-all-files" data-select-all="unselect">unselect all</a></span><span class="report-files-actions-btn"><input id="submit-report-selections" type="submit" value="${dct_action}" class="btn btn-primary rep-sel-action-${dct_action.replace(' ', '-')}"/></span>`;
    var $t = $outer.find('table.report-table, .report-list[data-results-count]');
    $f.insertBefore($t);
    $t.appendTo($outer.find('#itemselection-for-report'));

    // On select all / unselect all
    // check or uncheck all the entries.
    // Briefly disable auto submit on the form, to avoid potentially
    // thousands of individual checkbox changes being submitted to the server.
    // Wait a moment then trigger the auto submit afterwards\
    $(document).off('click', '#report-select-all-files, #report-unselect-all-files');
    $(document).on('click', '#report-select-all-files, #report-unselect-all-files', function () {
      $f.addClass('report-select-prevent-auto-submit');
      const allels = $('.report-file-selector');
      const do_select = ($(this).attr('data-select-all') == 'select');
      if (do_select) {
        allels.attr('checked', true);
      }
      else {
        allels.attr('checked', null);
      }

      window.setTimeout(function () {
        $f.removeClass('report-select-prevent-auto-submit');
        _fpa.reports.submit_selections();
      }, 100);
    });

    // For any individual selector checkbox submit selection
    $(document).off('change', 'input.report-file-selector');
    $(document).on('change', 'input.report-file-selector', function () {
      window.setTimeout(function () {
        _fpa.reports.submit_selections();
      }, 100);
    });

    var res = $t.find('thead th').each(function () {
      if ($(this).find('p:first').html() == dct) {
        $(this).addClass('no-sort');
        $(this).append(b);
        $(this).attr('title', null);
      }
    });

    if (res.length === 0)
      $t.prepend(b);

    // Don't add the default item below for download files, since we don't want to add a null item to the request and
    // there is no need to be able to send an empty list request
    if (dct_action == 'download files')
      return;

    // Add a default item that will allow all items to be removed if needed. Without this, there must always be at least one
    // result sent.
    var $el = $outer.find('#seicb-0').clone();
    var jel = $el.val();
    //  If no results were returned, or all the fields were blank, return
    if (!jel) return;

    $el.prop('id', 'seicb-default');
    var defval = JSON.parse(jel);
    defval.id = null;
    defval.init_value = true;
    $el.val(JSON.stringify(defval));
    $el.attr('checked', true)
    $el.attr('disabled', null)
    $el.attr('class', 'report-file-selector-default')
    $el.hide();
    console.log($el);
    $outer.find('.report-files-actions').append($el);


  },

  // If the update list, add to list or remove from list submit buttons are 
  // hidden, and the form is not marked to prevent auto submit,
  // then submit the recent changes to the list
  submit_selections: function () {
    var $form = $('#itemselection-for-report');
    var $submit = $form.find('#submit-report-selections');

    if ($submit.is(':visible') || $form.hasClass('report-select-prevent-auto-submit')) {
      return;
    }

    $submit[0].click();

    var $modal = $form.parents('.modal').first();
    if ($modal.length) {

      $modal.not('.has-mfcbb-clear').on('hidden.bs.modal', function () {
        $modal.find('.modal-footer .modal-footer-caption-before-button').html('');
      }).addClass('has-mfcbb-clear');

      $modal.find('.modal-footer .modal-footer-caption-before-button').html('selected items automatically saved')
    }

  },

  run_autos: function (sel) {
    if (!sel) sel = '.report-auto';
    $(sel).each(function () {
      var t = $(this);
      var id = t.attr('data-report-id');
      _fpa.ajax_working(t);
      $.ajax({
        url: '/reports/' + id + '.json?search_attrs=_use_defaults_',
        success: function (data) {
          _fpa.ajax_done(t);
          var res;
          var sa;
          if (data && data.search_attributes) {
            sa = "";

            for (var i in data.search_attributes) {
              if (data.search_attributes.hasOwnProperty(i) && i !== 'ids_filter_previous' && i !== '_use_defaults_') {
                var d = data.search_attributes[i];
                sa += '<div class="report-search-attr"><span class="attr-label">' + i + '</span><span class="attr-val">' + _fpa.utils.pretty_print(d, { return_string: true }) + '</span></div>';
              }
            }

            //sa = JSON.stringify(data.search_attributes, null, '<div>  ').replace(/\{/g, '<div>  ').replace(/\}/g, '</div>').replace(/\"|\[|\]|/g, '').replace(/_/g ,' ');
          }
          if (data && data.results && data.results[0]) {
            // res = JSON.stringify(data.results, null, '  ').replace(/\{/g, '<div>  ').replace(/\},?/g, '</div>').replace(/\"|\[|\]|/g, '');
            var rcount = data.results.length;
            if (rcount == 1)
              res = rcount + ' result';
            else
              res = rcount + ' results';

          } else {
            res = '-';
          }
          t.find('.report-measure').html(res);
          if (sa)
            t.find('.report-search-attr').html(sa);
        }
      });

    });
  },

  get_results_block: function () {
    return $('#embed_results_block,#master_results_block').last();
  },

  custom_results_handling: function (block, data) {
    _fpa.reports_custom_handling.handle(block, data);
  }


};
_fpa.reports_custom_handling = class {
  static handle(block, data) {

    const inst = new _fpa.reports_custom_handling(block, data);
    inst.run_handlers();
  }

  // Add an implementation for a named handler.
  // fn must be function() to retain current *this*
  // See 'test' example at the end of this file
  static add_handler_implementation(name, fn) {
    _fpa.reports_custom_handling.prototype[name] = fn;
  }

  constructor(block, data) {
    console.log('handle')
    this.$block = block;
    this.data = data;
    const handler_list = block.find('[data-result-handlers]').attr('data-result-handlers');
    if (!handler_list) return;

    this.handler_names = handler_list.split(' ');
    // Add new handler methods directly to this call if they are to be called
  }

  run_handlers() {
    const _this = this;
    if (!this.handler_names) return;

    this.handler_names.forEach((handler_name) => {
      if (!_this[handler_name]) {
        console.log(`run_handlers did not find handler: ${handler_name} in ${_this}`);
        return;
      }
      _this[handler_name]();
    });
  }
}

// Example of how to add a custom handling implementation
_fpa.reports_custom_handling.add_handler_implementation('test', function () {
  console.log(this.$block);
  console.log(this.data);
});
_fpa.reports_custom_handling.add_handler_implementation('array_field_to_blocks', function () {
  var first = null;
  var all_items = [];
  const $block = this.$block;

  const $list_cell = $block.find('td[data-col-type="array_field_to_blocks_items"]')
  const all_items_text = $list_cell.first().text();
  if (all_items_text && all_items_text != '' && all_items_text != '[nil]') {
    all_items = JSON.parse(all_items_text)
  }
  $block.find('[data-col-type="array_field_to_blocks_items"]').hide();

  // Handle the header
  var $th = $block.find('th[data-col-name="array_field_to_blocks"]');
  $th.hide();
  let newth = '';
  for (let i = 0; i < all_items.length; i++) {
    newth = `${newth}<th class="added"><span class="added-label">${all_items[i]}</span></th>`
  }
  $th.after(newth);

  // Handle each row
  $block.find('td[data-col-type="array_field_to_blocks"]').each(function () {
    let h = $(this).text()
    let j = []
    if (h && h != '' && h != '[nil]') {
      j = JSON.parse(h)
    }

    let res = []
    for (let i = 0; i < all_items.length; i++) {
      res[i] = (j.indexOf(all_items[i]) >= 0)
    }
    let newh = '';
    for (let has in res) {
      newh = `${newh}<td class="rch-aftb gotitem gotitem-${res[has]}"></td>`
    }
    $(this).html('').after(newh)
  }).hide();

});
_fpa.reports_custom_handling.add_handler_implementation('expand_all_tree', function () {
  const $new = $('<a href="#">expand all</a>');
  $('th[data-col-name="id0"] p.table-header-col-type').html($new);
  $new.on('click', function (ev) {
    const $a = $('th[data-col-name="id0"] p.table-header-col-type a');
    const orig_text = $a.text();
    $a.text('...');

    window.setTimeout(function () {
      if (orig_text == 'expand all') {
        $('tr[data-tt-id]').each(function () { $(this)[0].trExpand(true) })
        $a.text('shrink all')
      }
      else {
        $('tr[data-tt-id]').each(function () { $(this)[0].trCollapse(true) })
        $a.text('expand all')
      }
    });

    ev.preventDefault();
  })
});
_fpa.reports_custom_handling.add_handler_implementation('expand_subitems_tree', function () {
  $('table').not('.added-expand_subitems_tree').on('click', 'td[data-col-type="id0"] img[id="state"]', function () {
    const $tr = $(this).parents('tr').first();
    var ttid = $tr.attr('data-tt-id');
    console.log(ttid);
    console.log($tr[0].trChildrenVisible);
    if (!$tr[0].trChildrenVisible) return

    $(`tr[data-tt-parent-id="${ttid}"]`).each(function () {
      const tr = $(this)[0];
      tr.trExpand(true)
    })
  }).addClass('added-expand_subitems_tree');
});  
_fpa.reports_custom_handling.add_handler_implementation('pre_fully_expanded', function () {
  $('table pre.expandable').removeClass('expandable');
});  
// Report results handler for opening documentation within the sidebar
_fpa.reports_custom_handling.add_handler_implementation('sidebar_hash_content_links', function () {

  const $block = this.$block;
  window.setTimeout(function () {

    const target = "table td[data-col-type] a[href^='/content']";
    $(target).each(function (ev) {
      let href = $(this).attr('href');

      $(this)
        .attr('target', '_blank')
        .attr('data-remote', 'true')
        .attr('data-toggle', 'uncollapse')
        .attr('data-target', '#help-sidebar')
        .attr('data-working-target', '#help-sidebar-body')
        .attr('data-orig-href', href);

      // Prevent the outer page reloading
      $(this).parents('.standalone-page-col').attr('data-no-load', 'true');
    })

    $block.on('click', target, function (ev) {
      let href = $(this).attr('href');
      let hash = href.split('#')[1];
      if (hash) hash = `#${hash}`;
      $('#help-sidebar').collapse('show').attr('data-onload-scrollto', hash);
      ev.preventDefault();
    });
  }, 500);
});


// Show a table as a tree. The attribute data-tt-tree-cols 
// defines the set of columns to use for grouping (JSON array)
// param $table - jQuery reference to table
_fpa.reports_tree = class {

  static show_table_as_tree($table) {
    if (!$table.hasClass('tree-table') || $table.hasClass('tree-table-setup')) return;

    $table.addClass('tree-table-setup')
    window.setTimeout(() => {
      let tree = new _fpa.reports_tree($table);
      tree.setup()
      tree.setup_header()
      tree.setup_rows()
      tree.finalize()
    }, 100)
  }

  constructor(table) {
    this.$table = table;
  }


  setup() {
    const this_class = this;

    if (this.$table.hasClass('jsTree')) return;

    this.$table.addClass('added-tree-table');
    const col_levels = this.$table.attr('data-tt-tree-cols');
    const num_levels = this.$table.attr('data-tt-tree-num-levels');
    const default_expand = this.$table.attr('data-tt-tree-expand-level');

    if (col_levels)
      this.col_levels = JSON.parse(col_levels);
    else
      this.col_levels = [];

    if (num_levels)
      this.num_levels = parseInt(num_levels);
    else
      this.num_levels = 2;

    if (default_expand)
      this.default_expand = parseInt(default_expand);
    else
      this.default_expand = 0;

    if (this.col_levels.length != this.num_levels - 1) {
      console.log("ERROR - the number of levels specified for the tree does not correspond to the column levels specified");
      return;
    }
  }

  setup_header() {
    const this_class = this;

    // Add rows for additional levels

    const $head_row = this_class.$table.find('thead tr');
    let sub_rows = [null]

    for (let i = this_class.num_levels - 1; i >= 1; i--) {
      let $new_row = $(`<tr data-tt-thtr-row="${i}" class="tt-head-sub-row"></tr>`)
      $head_row.after($new_row)
      sub_rows[i] = $new_row
    }

    $head_row.addClass('tt-head-main-row');
    $head_row.attr('data-tt-thtr-row', '0');

    // Add classes and attributes to the header columns to aid styling and shift to sub rows
    const $head_cells = this_class.$table.find('thead th[data-col-type]');
    $head_cells.each(function () {
      if (this_class.col_levels[0].indexOf($(this).attr('data-col-name')) >= 0) {
        $(this).addClass('is-parent-col')
      }
      else {
        $(this).addClass('is-not-parent-col')
      }

      for (let i = 0; i < this_class.num_levels; i++) {
        if (i > 0 && $(this).attr('data-col-name') == `id${i}`) {
          $(this).css({ visibility: 'hidden' })
        }

        let rownum = null;
        if (i == this_class.num_levels - 1) {
          rownum = this_class.num_levels - 1;
        }
        else if (this_class.col_levels[i].indexOf($(this).attr('data-col-name')) >= 0) {
          rownum = i;
        }

        if (rownum != null) {
          $(this).attr('data-tt-th-col-level', i)
          if (rownum > 0) {
            sub_rows[rownum].append($(this))
          }
          break;
        }

      }
    });

    this_class.num_cols = $head_cells.length;

  }

  // Run through the rows to add an extra row above a group of rows with the same ID,
  // to act as the parent tree row for that group of data.
  // The primary columns that appear in each of these group headers are blanked in the
  // subsequent data rows to avoid repetition and provide a tree view
  setup_rows() {

    const this_class = this;
    var $rows = this_class.$table.find('tbody tr');
    this_class.prev_id = [];


    $rows.each(function () {
      this_class.num_ancestor_cols = 0;
      for (let curr_level = 0; curr_level < this_class.num_levels - 1; curr_level++) {
        this_class.handle_row_level($(this), curr_level);
      }
    });

    $rows.find(`[data-col-type="id${this_class.num_levels - 1}"]`).show().css({ visibility: 'hidden' });
  }

  finalize() {
    const this_class = this;
    com_github_culmat_jsTreeTable.treeTable(this_class.$table);
    this_class.$table.expandLevel(this_class.default_expand);
  }

  handle_row_level($row, curr_level) {
    const this_class = this;

    const $id = $row.find(`[data-col-type="id${curr_level}"]`)
    const id = $id.text() || `(no parent ID-${curr_level} set)`;
    const $next_level_id = $row.find(`[data-col-type="id${curr_level + 1}"]`);
    const next_level_id = $next_level_id.text() || `(no ID-${curr_level + 1} set)`;
    const this_level_cols = this_class.col_levels[curr_level];
    const num_this_level_cols = this_level_cols.length;

    // Hide other ids. Show this one, unless we are at the deepest level
    for (let i = 0; i < this_class.num_levels; i++) {
      let vis = (curr_level == i) ? 'visible' : 'hidden';
      let $cell = $row.find(`[data-col-type="id${i}"]`);
      $cell.css({ visibility: vis });
      let idval = $cell.text() || `(no ID-${i} set)`;

      $cell.html(`<treeid>${idval}</treeid>`)
    }
    $id.show();


    if (id != this_class.prev_id[curr_level]) {
      if (curr_level == 0) {
        this_class.prev_id = [];
      }
      // A new id, so add the parent row for it
      var $par = $row.clone();

      $par.find('[data-col-type]').each(function () {
        let col_type = $(this).attr('data-col-type');
        if (this_level_cols.indexOf(col_type) < 0) {
          $(this).remove();
        }
      });

      let pad_cols = this_class.num_cols - num_this_level_cols - curr_level;
      $par.find('[data-col-type]').last().attr('colspan', pad_cols);

      $par.attr('data-tt-id', `${id}`);
      $row.before($par);
    }

    $row.find('[data-col-type]').each(function () {
      if (this_level_cols.indexOf($(this).attr('data-col-type')) >= 0) {
        $(this).remove();
        //.addClass('is-parent-col').html('')
      }
    });


    $row.attr('data-tt-id', `${next_level_id}`);
    $row.attr('data-tt-parent-id', id);

    for (let i = 1; i < this_class.num_levels; i++) {
      $row.find(`[data-col-type="id${i}"]`).hide();
    }

    this_class.num_ancestor_cols = this_class.num_ancestor_cols + num_this_level_cols;
    this_class.prev_id[curr_level] = id;
  }
};
"use strict";

var SecureViewAppSpecific = function () {
  var _this = this;

  this.setup = function (secure_view) {

    this.secure_view = secure_view;

    this.$show_files = $('#sv-extra-actions-show_files');

    this.$show_files.not('.sv-added-click-ev').on('click', function (ev) {
      var $owner_el = _this.secure_view.$owner_el;
      var $el = $owner_el;

      if ($el.hasClass('sv-file-listing')) {
        // The folder is shown - hide it
        _this.close_folder();
      }
      else {
        //  The folder is not shown - show it
        $el.addClass('sv-file-listing');
        $(this).addClass('glyphicon-folder-close');
        $(this).removeClass('glyphicon-folder-open');
        $owner_el.find('a.refresh-container-list').attr('disabled', true);
      }
      ev.preventDefault();
    }).addClass('sv-added-click-ev');

    this.$search_doc = $('#sv-extra-actions-search_doc, #sv-close-search');
    this.$search_doc.not('.sv-added-click-ev').on('click', function (ev) {
      var $search_panel = _this.secure_view.$search_panel;

      if ($search_panel.hasClass('sv-search-panel')) {
        // The panel is shown - hide it
        _this.close_search_panel();
      }
      else {
        //  The panel is not shown - show it
        _this.show_search_panel();
      }
      ev.preventDefault();
    }).addClass('sv-added-click-ev');


    this.close_folder();

    return this;
  }

  this.close = function () {
    this.close_folder();
    this.close_search_panel();
  }

  this.close_folder = function () {
    // Close the folder if it is open
    this.secure_view.$owner_el.removeClass('sv-file-listing');
    this.$show_files.addClass('glyphicon-folder-open');
    this.$show_files.removeClass('glyphicon-folder-close');
    this.secure_view.$owner_el.find('a.refresh-container-list').attr('disabled', false);

  }

  this.show_search_panel = function () {
    this.secure_view.$search_panel.addClass('sv-search-panel').animate({ width: '250px' });
    this.secure_view.$search_results.html('');
    this.secure_view.$search_form.find('[name="search_string"]').val('').focus();
  }

  this.close_search_panel = function () {
    this.secure_view.$search_panel.removeClass('sv-search-panel').animate({ width: '0' });
  }

};
class UserPreferences {

    static date_format() {
        const df = {
            'mm/dd/yyyy': 'MM/dd/yyyy',
            'dd/mm/yyyy': 'dd/MM/yyyy',
        };
        return df[_fpa.state.current_user_preference.date_format];
    }

    static date_time_format(with_seconds = false) {

        const seconds = (with_seconds ? ':ss' : '')
        const dtf = {
            'mm/dd/yyyy 24h:mm': `MM/dd/yyyy HH:mm${seconds}`,
            'mm/dd/yyyy hh:mm am/pm': `MM/dd/yyyy h:mm${seconds} a`,
            'dd/mm/yyyy hh:mm am/pm': `dd/MM/yyyy h:mm${seconds} a`,
            'dd/mm/yyyy 24h:mm': `dd/MM/yyyy HH:mm${seconds}`,
        };
        return dtf[_fpa.state.current_user_preference.date_time_format];
    }

    static time_format(with_seconds = false) {
        const seconds = (with_seconds ? ':ss' : '')
        const tf = {
            'hh:mm am/pm': `h:mm${seconds} a`,
            '24h:mm': `H:mm${seconds}`
        };
        return tf[_fpa.state.current_user_preference.time_format];
    }

    static timezone() {
        return _fpa.state.current_user_preference.timezone_iana;
    }
};
